/** Box point → content point (inverse transform). */
export function toContent(t: ZoomPan, sx: number, sy: number): Pt {
  return [(sx - t.x) / t.s, (sy - t.y) / t.s];
}

/** Wheel delta → zoom factor (smooth for trackpads, stepped for wheels). */
